//! Engine Note code table: `(source, n)` -> name, default level and the registered `v[]` fields.
//! Generated by `cargo xtask gen-schema` from hft-event `NOTE_NAMES` and the source crates'
//! `NOTE_CODES` tables; do not edit. Strategy codes are not in this table.

/// One engine Note code.
#[derive(Copy, Clone, Debug)]
pub struct NoteEntry {
    /// `source << 24 | n`.
    pub code: u32,
    /// `NoteSource` value.
    pub source: u8,
    pub n: u32,
    pub name: &'static str,
    /// Default `NoteLevel` value; 0 = by condition or owned by the source crate.
    pub level: u8,
    /// `(name, bit, bits)` of the `v[]` fields listed in the registry.
    pub v: &'static [(&'static str, u16, u16)],
}

pub static NOTES_CATALOG: &[NoteEntry] = &[
];
